import React, { useState } from 'react';
import { EmotionAnalysis, RiskAssessment, EmotionStyle } from '../types';

interface ReportPanelProps {
  emotion: EmotionAnalysis;
  risk: RiskAssessment;
  emotionStyle: EmotionStyle;
  report: string;
}

export const ReportPanel: React.FC<ReportPanelProps> = ({ emotion, risk, emotionStyle, report }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const emotionNames: Record<string, string> = {
    happy: '开心',
    sad: '低落',
    anxious: '焦虑',
    angry: '愤怒',
    lonely: '孤独',
    neutral: '平稳'
  };

  const riskNames: Record<string, string> = {
    low: '低',
    medium: '中',
    high: '高',
    critical: '严重'
  };

  const riskColors: Record<string, string> = {
    low: '#4CAF50',
    medium: '#FF9800',
    high: '#F44336',
    critical: '#9C27B0'
  };

  const handleExport = () => {
    const blob = new Blob([report], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `心理咨询报告_${new Date().toLocaleDateString('zh-CN').replace(/\//g, '-')}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="report-panel">
      <div className="report-header" onClick={() => setIsExpanded(!isExpanded)}>
        <div className="report-title">
          <span className="report-icon">📋</span>
          <span>心理咨询报告</span>
        </div>
        <div className="report-toggle">
          {isExpanded ? '▼' : '▶'}
        </div>
      </div>

      {isExpanded && (
        <div className="report-content">
          <div className="report-section">
            <div className="section-title">情绪分析</div>
            <div className="emotion-card" style={{ borderColor: emotionStyle.color }}>
              <div className="emotion-header">
                <span className="emotion-badge" style={{ backgroundColor: emotionStyle.color }}>
                  {emotionNames[emotion.emotion]}
                </span>
                <span className="confidence">置信度: {(emotion.confidence * 100).toFixed(0)}%</span>
              </div>
              {emotion.keywords.length > 0 && (
                <div className="emotion-keywords">
                  <span className="keywords-label">关键词:</span>
                  {emotion.keywords.map((kw, i) => (
                    <span key={i} className="keyword-tag">{kw}</span>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="report-section">
            <div className="section-title">风险评估</div>
            <div className="risk-card" style={{ borderColor: riskColors[risk.level] }}>
              <div className="risk-header">
                <span
                  className="risk-badge"
                  style={{ backgroundColor: riskColors[risk.level] }}
                >
                  风险等级: {riskNames[risk.level]}
                </span>
              </div>
              {risk.keywords.length > 0 && (
                <div className="risk-keywords">
                  <span className="keywords-label">预警关键词:</span>
                  {risk.keywords.map((kw, i) => (
                    <span key={i} className="keyword-tag warning">{kw}</span>
                  ))}
                </div>
              )}
              {risk.warningMessage && (
                <div className="warning-message" style={{ borderColor: riskColors[risk.level] }}>
                  ⚠️ {risk.warningMessage}
                </div>
              )}
              <div className="hotline">{risk.hotline}</div>
            </div>
          </div>

          <div className="report-section">
            <div className="section-title">完整报告</div>
            <div className="full-report">
              <pre>{report}</pre>
            </div>
          </div>

          <div className="report-actions">
            <button className="action-btn export-btn" onClick={handleExport}>
              📥 导出报告
            </button>
          </div>
        </div>
      )}
    </div>
  );
};
